"""Integrity checks for the synthetic fixtures generated by fixtures/make_fixtures.py."""

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path

from tests.helpers import FAKE_SECRETS, FIXTURES_DIR, PAIR_MARKERS, fixture_names, load_bytes

EXPECTED_NAMES = {
    "demo_weather.jsonl", "pair_fail.jsonl", "pair_pass.jsonl", "no_tests.jsonl", "truncated_output.jsonl",
    "no_exit_code.jsonl", "code_changed.jsonl", "unsupported_runner.jsonl", "secrets.jsonl",
    "many_requests.jsonl", "malformed.jsonl", "meta_only.jsonl", "runners.jsonl",
}
METADATA = {"parentUuid", "uuid", "sessionId", "cwd", "version", "gitBranch", "userType", "isSidechain", "timestamp"}


def load_generator():
    spec = importlib.util.spec_from_file_location("make_fixtures", FIXTURES_DIR.parent / "make_fixtures.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def classify_lines(data: bytes) -> tuple[list[dict], dict[int, str]]:
    """Records, and line number -> "invalid_json" | "not_object" for every line that is not a JSON object."""
    records, bad = [], {}
    for number, line in enumerate(data.decode("utf-8").splitlines(), 1):
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            bad[number] = "invalid_json"
            continue
        if isinstance(value, dict):
            records.append(value)
        else:
            bad[number] = "not_object"
    return records, bad


class FixtureFilesTest(unittest.TestCase):
    def test_expected_files_exist(self):
        self.assertEqual(set(fixture_names()), EXPECTED_NAMES)

    def test_every_line_is_a_json_object_except_two_in_malformed(self):
        for name in fixture_names():
            with self.subTest(name=name):
                data = load_bytes(name)
                self.assertTrue(data.endswith(b"\n"))
                self.assertNotIn(b"\n\n", data)
                _, bad = classify_lines(data)
                expected = ["invalid_json", "not_object"] if name == "malformed.jsonl" else []
                self.assertEqual(sorted(bad.values()), expected)

    def test_conversation_records_carry_metadata_to_drop(self):
        for name in fixture_names():
            records, _ = classify_lines(load_bytes(name))
            for record in records:
                if record["type"] in ("user", "assistant", "system"):
                    with self.subTest(name=name, uuid=record.get("uuid")):
                        self.assertLessEqual(METADATA, set(record))
                        if record["type"] == "assistant":
                            self.assertIn("requestId", record)
                            self.assertLessEqual({"id", "model", "usage"}, set(record["message"]))

    def test_pair_files_differ_only_on_the_target_result(self):
        fail = load_bytes("pair_fail.jsonl").splitlines()
        passed = load_bytes("pair_pass.jsonl").splitlines()
        self.assertEqual(len(fail), len(passed))
        differing = [i for i, (a, b) in enumerate(zip(fail, passed, strict=True)) if a != b]
        self.assertEqual(len(differing), 1)
        target = differing[0]
        cases = ((fail, PAIR_MARKERS[0], True, "1 failed, 3 passed in 0.40s"), (passed, PAIR_MARKERS[1], False, "4 passed in 0.40s"))
        for lines, marker, is_error, summary in cases:
            with self.subTest(marker=marker):
                block = json.loads(lines[target])["message"]["content"][0]
                use = json.loads(lines[target - 1])["message"]["content"][0]
                self.assertEqual((use["name"], use["input"]["command"]), ("Bash", "pytest -q"))
                self.assertEqual((block["type"], block["tool_use_id"]), ("tool_result", use["id"]))
                self.assertIs(block["is_error"], is_error)
                self.assertEqual(block["content"].startswith("Exit code 1\n"), is_error)
                self.assertTrue(block["content"].endswith(summary))
                self.assertIn(marker, block["content"])
                others = b"\n".join(lines[:target] + lines[target + 1 :])
                for any_marker in PAIR_MARKERS:
                    self.assertNotIn(any_marker.encode(), others)

    def test_regeneration_is_byte_identical(self):
        generator = load_generator()
        with tempfile.TemporaryDirectory() as tmp:
            generator.write_fixtures(Path(tmp))
            regenerated = sorted(path.name for path in Path(tmp).iterdir())
            self.assertEqual(regenerated, fixture_names())
            for name in regenerated:
                with self.subTest(name=name):
                    self.assertEqual((Path(tmp) / name).read_bytes(), load_bytes(name))

    def test_every_fake_secret_is_really_in_the_fixtures(self):
        # Keeps FAKE_SECRETS in sync with the generator; a value missing here would make leak checks vacuous.
        raw = load_bytes("demo_weather.jsonl") + load_bytes("secrets.jsonl")
        for value in FAKE_SECRETS:
            with self.subTest(value=value):
                self.assertIn(value.encode(), raw)


if __name__ == "__main__":
    unittest.main()
